"""Regenerate the add-on's copies of scrimmage code (run from the repo: python freecad/sync.py)."""

import shutil
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
PART = ROOT / "freecad" / "Scrimmage" / "scrimmage_part"


def main() -> None:
    sys.path.insert(0, str(ROOT))
    from scrimmage.motors import MOTORS
    shutil.copyfile(ROOT / "scrimmage" / "parts" / "toml_writer.py", PART / "toml_writer.py")
    names = ",\n".join(f"    {n!r}" for n in sorted(MOTORS))
    (PART / "motors.py").write_text(
        '"""Motor names the panel offers. GENERATED by freecad/sync.py from scrimmage.motors.MOTORS; do not edit."""\n\n'
        f"MOTOR_NAMES = (\n{names},\n)\n")


if __name__ == "__main__":
    main()
